// tw_rom — レーン P のひねり係数 W8192^(P·k1)（k1 = 0..511）。**tools/gen_tw_rom.py の生成物。手で直さない**
//
// 出力はアドレスから **2 クロック後**（ROM の読み出し + 出力レジスタ）。
// 値は round(2^16 · exp(-2πi·P·k1/8192))、18 bit 符号付き。

`timescale 1ns / 1ps

module tw_rom #(
    parameter integer P = 0
)(
    input  wire               clk,
    input  wire [8:0]         addr,
    output reg  signed [17:0] w_re,
    output reg  signed [17:0] w_im
);
    // 1 語 36 bit = {im[17:0], re[17:0]}（生成物を小さくするため 16 進 1 語にまとめている）
    reg [35:0] r;
    always @(posedge clk) begin
        w_re <= r[17:0];
        w_im <= r[35:18];
    end

